import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"45、【萃】 坤下兑上","description":"周易尚氏学 - 45、【萃】 坤下兑上","frontmatter":{"title":"45、【萃】 坤下兑上","description":"周易尚氏学 - 45、【萃】 坤下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/050.md","filePath":"zh/classics/shangshi/050.md"}'),h={name:"zh/classics/shangshi/050.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_45、【萃】-坤下兑上" tabindex="-1">45、【萃】 坤下兑上 <a class="header-anchor" href="#_45、【萃】-坤下兑上" aria-label="Permalink to “45、【萃】 坤下兑上”">​</a></h1><p>苹聚也。坤为万物。聚于泽中。故曰萃。王谓五。艮为庙。假格通至也。巽为人。王假有庙。言王以至诚。格于宗庙而有事也。九五得位。故曰利见大人。二五应予。故曰亨利贞。兑为羊。巽为豕。坤为牛。皆大牲。有事于宗庙用之而吉也。利有攸往。谓二应五。五天位。故传曰顺天命。</p><p>彖曰。萃。聚也。顺以说。刚中而应。故聚也。王假有庙。致孝享也。利见大人亨。聚以正也。用大牲吉。利有攸往。顺天命也。观其所聚。而天地万物之情可见矣。</p><p>五天位。巽为命。坤顺。顺天命。谓二顺五也。艮为观。坤为万物。天地万物。阴阳而已。有阴阳即有情咸。可见而知也。</p><p>象曰。泽上于地。萃。君子以除戎器。戒不虞。</p><p>戎兵也。月令以习五戎。注五戎弓殳戈矛战也。兑为斧钺。艮为刀兵。除治也。君子观于革象。因以治戎器而戒不虞。坤为乱。艮为止。止乱。故曰戒不虞。言防意外也。</p><p>初六。有孚。不终。乃乱乃萃。若号。一握为笑。勿恤。往无咎。</p><p>四有应。故曰有孚。乃初为二三所阻格。难于应四。故曰不终。乃乱乃苹。坤为乱。为聚。言乱萃于下也。四巽为号。艮手为握。若号者。言四召初与相上下也。四下来初。则初四相握手。下卦成震。震为笑。故曰一握为笑也。坤为忧。有应故勿忧。初之四得正。故往无咎。</p><h3 id="象曰。乃乱乃萃。其志乱也。" tabindex="-1">象曰。乃乱乃萃。其志乱也。 <a class="header-anchor" href="#象曰。乃乱乃萃。其志乱也。" aria-label="Permalink to “象曰。乃乱乃萃。其志乱也。”">​</a></h3><p>坤为志为乱。</p><p>六二。引吉。无咎。孚乃利用禴。</p><p>引进也。礼檀弓。兄弟之子犹子也。盖引而进之也。引吉无咎者。言进应五则吉而无咎也。禴薄祭也。二孚五。五兑为享。而坤为吝啬。故曰孚乃利用禴，禴夏祭。互巽为夏也。</p><h3 id="象曰。引吉无咎。中未变也。" tabindex="-1">象曰。引吉无咎。中未变也。 <a class="header-anchor" href="#象曰。引吉无咎。中未变也。" aria-label="Permalink to “象曰。引吉无咎。中未变也。”">​</a></h3><p>进应五仍中位。故曰中未变。</p><p>六三。萃如嗟如。无攸利。往无咎。小吝。</p><p>三无应失位。而巽为嗟。故曰嗟如。巽为利。失位无应。故无所利。三前遇重阳。故往无咎。然上无应。故往小吝也。</p><h3 id="象曰。往无咎。上巽也。" tabindex="-1">象曰。往无咎。上巽也。 <a class="header-anchor" href="#象曰。往无咎。上巽也。" aria-label="Permalink to “象曰。往无咎。上巽也。”">​</a></h3><p>巽顺也。上巽言上顺四五。四五阳。故无咎。虞氏谓动之四故上卖。误之远矣。</p><p>九四。大吉无咎。</p><p>下乘三阴。故大吉。失位故无咎。无咎者仅免于咎也。</p><h3 id="象曰。大吉无咎。" tabindex="-1">象曰。大吉无咎。 <a class="header-anchor" href="#象曰。大吉无咎。" aria-label="Permalink to “象曰。大吉无咎。”">​</a></h3><p>位不当也系辞云。无咎者善补过者也。故无咎非全美之辞。</p><p>九五。萃有位。无咎。匪孚。元永贞。悔亡。</p><p>得位居中。故有位无咎。五孚于二。乃为四所阻。难于应二。故曰匪罕。然乾元永贞于五。居高临下。亦无悔也。</p><h3 id="象曰。萃有位。志未光也。" tabindex="-1">象曰。萃有位。志未光也。 <a class="header-anchor" href="#象曰。萃有位。志未光也。" aria-label="Permalink to “象曰。萃有位。志未光也。”">​</a></h3><p>兑为黯昧。艮为光明。艮伏故志未光。巽为志。</p><p>上六。赍咨涕洟。无咎。</p><p>兑为口。故咨。释文齐咨嗟叹之辞。郑同。马云。悲声怨声。兑为泽。故涕夷。玉篇目计出曰涕。说文。演鼻液也。上乘阳。三无应。故悲哀若是。然当位亦无大咎也。虞翻作齐资。云齐持资膊也。即持赙助丧也。非。</p><h3 id="象曰。齐咨涕夷。未安上也。" tabindex="-1">象曰。齐咨涕夷。未安上也。 <a class="header-anchor" href="#象曰。齐咨涕夷。未安上也。" aria-label="Permalink to “象曰。齐咨涕夷。未安上也。”">​</a></h3><p>言不安于穷吝。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
